def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    threat_bids = []
    desperate_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                affordable = min(opp.get('budget', 0) + opp.get('daily_salary', 0), bid)
                threat_bids.append(affordable)

    if not alive_opponents:
        if hp <= 3 or no_water >= 2:
            return float(min(budget, 42.0))
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    tight_supply = slots <= 1
    medium_supply = slots == 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_bids) if threat_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if tight_supply:
        urgency += 2
    elif medium_supply:
        urgency += 1

    urgency += min(2, desperate_count)

    if urgency >= 6:
        target = max(63.0, highest_threat + 2.0)
    elif urgency >= 4:
        target = max(48.0, highest_threat + 1.5)
    elif urgency >= 2:
        if highest_prev >= 120:
            target = 24.0 if hp > 4 and no_water == 0 else 56.0
        else:
            target = max(30.0, highest_threat * 0.55 + 4.0)
    else:
        if highest_prev >= 120:
            target = 14.0
        elif highest_prev >= 80:
            target = 18.0
        else:
            target = max(16.0, highest_threat * 0.35 + 3.0)

    if day >= 8:
        target += 6.0
    elif day >= 6 and (hp <= 4 or no_water >= 1):
        target += 4.0

    reserve_floor = 0.0
    if day <= 5:
        reserve_floor = 35.0
    elif day <= 8:
        reserve_floor = 20.0

    max_spend = max(0.0, budget - reserve_floor)
    if urgency >= 5:
        max_spend = budget
    elif urgency >= 3:
        max_spend = max(max_spend, budget * 0.7)

    bid = min(target, max_spend, budget)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, highest_threat + 3.0, 69.0))

    if bid < 0:
        bid = 0.0

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0

    # Estimate how competitive we need to be.
    # If someone previously bid near the daily salary ceiling, we assume they are willing to pay to secure water.
    # We undercut slightly unless our HP is critical.
    critical_hp = 3.0
    low_hp = hp <= critical_hp

    # Base target: aim around half salary normally, but react to high previous bids.
    # If highest_prev_bid is high, we bid to be competitive but not max.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if low_hp:
            target = min(budget, DAILY_SALARY * 0.75)
        else:
            target = min(budget, max(DAILY_SALARY * 0.55, highest_prev_bid * 0.85))
    else:
        # If bids were moderate, bid slightly above the second-highest to secure allocation.
        if second_prev_bid > 0:
            target = max(DAILY_SALARY * 0.5, second_prev_bid + 1.0)
        else:
            target = DAILY_SALARY * 0.55

    # If we've already had no-water days, increase urgency.
    if no_water_days >= 2:
        target *= 1.15
    if no_water_days >= 3:
        target *= 1.25

    # If supply is tight relative to requirement, slightly increase.
    # (We only have current supply; higher supply reduces urgency.)
    # supply in [15,25], WATER_REQ=9 => urgency highest when supply is 15.
    if supply <= 16.0:
        target *= 1.08
    elif supply >= 22.0:
        target *= 0.95

    # Final clamp to budget and non-negative.
    bid = max(0.0, min(float(budget), float(target)))

    # Avoid bidding tiny amounts late if we are at risk.
    if day >= 7 and low_hp and bid < DAILY_SALARY * 0.3:
        bid = min(float(budget), DAILY_SALARY * 0.45)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.3)

    bid_factor = 0.7

    if my_hp <= 2:
        bid_factor = 1.0
    elif my_hp <= 4:
        bid_factor = 0.9
    elif my_hp >= 8 and my_budget > DAILY_SALARY * 2:
        bid_factor = 0.6

    if my_no_water_days > 0:
        bid_factor += my_no_water_days * 0.1

    supply_scarcity_ratio = 1 - ((current_supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))
    bid_factor += supply_scarcity_ratio * 0.15

    yesterday_opponent_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_opponent_bids.append(prev_trace['bid'])

    if yesterday_opponent_bids:
        max_opp_bid_yesterday = max(yesterday_opponent_bids)
        avg_opp_bid_yesterday = sum(yesterday_opponent_bids) / len(yesterday_opponent_bids)

        if max_opp_bid_yesterday > DAILY_SALARY * 0.9:
            bid_factor = max(bid_factor, 1.0)
        elif (DAILY_SALARY * bid_factor) < avg_opp_bid_yesterday * 1.05:
            bid_factor = max(bid_factor, (avg_opp_bid_yesterday * 1.05) / DAILY_SALARY)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp <= 3:
            bid_factor = max(bid_factor, 1.1)
        elif my_hp > 3 and my_budget > DAILY_SALARY:
            bid_factor = max(bid_factor, 0.85)

    calculated_bid = DAILY_SALARY * bid_factor

    final_bid = min(my_budget, calculated_bid)
    final_bid = max(1.0, final_bid)

    return final_bid
